const searches = await Promise.all([
  tools.search({ namespace: "vercel_api.user.personalvercelapi", query: "environment variables", limit: 20 }),
  tools.search({ namespace: "vercel_api.user.personalvercelapi", query: "projects", limit: 20 }),
  tools.search({ namespace: "vercel_api.user.personalvercelapi", query: "deployments", limit: 20 })
]);
return searches.map((s) => s.items.map(({ path, description }) => ({ path, description })));

