const [projectResult, envResult] = await Promise.all([
  tools.vercel_api.user.personalvercelapi.projects.getProject({ idOrName: "bundjil-codex-proxy" }),
  tools.vercel_api.user.personalvercelapi.projects.filterProjectEnvs({ idOrName: "bundjil-codex-proxy", decrypt: "false" })
]);
if (!projectResult.ok) return { projectError: projectResult.error.code };
if (!envResult.ok) return { envError: envResult.error.code };
const envData = envResult.data;
const envs = Array.isArray(envData) ? envData : ("envs" in envData ? envData.envs : [envData]);
const relevant = envs.filter((env) => env.key.startsWith("BUNDJIL_") || env.key.startsWith("KV_REST_API_") || env.key.startsWith("UPSTASH_REDIS_")).map((env) => ({
  key: env.key,
  target: env.target,
  type: env.type,
  integrationBacked: env.configurationId != null || env.contentHint != null,
  contentHintType: env.contentHint?.type ?? null
})).sort((a,b) => a.key.localeCompare(b.key));
const previews = (projectResult.data.latestDeployments ?? []).filter((deployment) => deployment.target === null || deployment.target === undefined || deployment.target === "preview");
const latestPreview = previews.sort((a,b) => b.createdAt - a.createdAt)[0];
return {
  project: {
    name: projectResult.data.name,
    rootDirectory: projectResult.data.rootDirectory,
    framework: projectResult.data.framework,
    nodeVersion: projectResult.data.nodeVersion,
    buildCommand: projectResult.data.buildCommand,
    outputDirectory: projectResult.data.outputDirectory,
    integrationCount: projectResult.data.integrations?.length ?? 0
  },
  relevant,
  productionBundjilCount: relevant.filter((env) => env.key.startsWith("BUNDJIL_") && (env.target === "production" || (Array.isArray(env.target) && env.target.includes("production")))).length,
  latestPreview: latestPreview ? { readyState: latestPreview.readyState, createdAt: latestPreview.createdAt, target: latestPreview.target ?? "preview" } : null
};

