   221	                message: "Unable to encode Codex OAuth profile.",
   222	                cause,
   223	              })
   224	          )
   225	        );
   226	        yield* Ref.update(
   227	          state,
   228	          (profiles) => new Map([...profiles, [key, profile] as const])
   229	        );
   230	      }),
   231	      removeProfile: Effect.fn("CodexProfileStoreMemory.removeProfile")(
