   253	export const CodexProfileStoreMemory = (
   254	  profiles: readonly CodexOAuthProfileType[] = []
   255	) =>
   256	  CodexProfileStoreMemoryLive.pipe(
   257	    Layer.provide(CodexOAuthMemoryProfilesLive(profiles))
   258	  );
