   260	export const CodexOAuthProfileCommitMemory = Layer.effect(
   261	  CodexOAuthProfileCommit,
   262	  Effect.gen(function* makeCodexOAuthProfileCommitMemory() {
   263	    const state = yield* CodexOAuthMemoryProfiles;
   264	    const observer = yield* Effect.serviceOption(CodexOAuthObserver);
   265	
   266	    const writeProfile = (
   267	      operation: CodexOAuthProfileCommitOperation,
   268	      profile: CodexSubscriptionProfile,
   269	      expectedRevision?: CodexSubscriptionProfile["credentialRevision"],
   270	      expectedLegacyProfile?: CodexAccessTokenImportProfileType
   271	    ) =>
   272	      Effect.gen(function* writeProfileCommit() {
   273	        const key = yield* codexOAuthProfileStorageKey(profile.subject);
   274	        const subjectHash = yield* codexOAuthProfileSubjectHash(
   275	          profile.subject
   276	        );
