   278	          Effect.mapError(
   279	            (cause) =>
   280	              new OAuthProfileSchemaError({
   281	                boundary: "CodexOAuthProfile",
   282	                message: "Unable to encode committed Codex OAuth profile.",
   283	                cause,
   284	              })
   285	          )
   286	        );
   287	        const conflict = yield* Ref.modify(state, (profiles) => {
   288	          const currentProfile = profiles.get(key);
   289	          const currentRevision =
   290	            currentProfile?.profileKind === "subscription"
   291	              ? currentProfile.credentialRevision
   292	              : undefined;
   293	          const initialConflict =
   294	            operation === "initialWrite" && currentProfile !== undefined;
   295	          const legacyReplacementConflict =
   296	            operation === "replaceLegacy" &&
   297	            (currentProfile?.profileKind !== "access-token-import" ||
   298	              currentProfile !== expectedLegacyProfile);
   299	          const casConflict =
   300	            operation !== "initialWrite" &&
   301	            operation !== "replaceLegacy" &&
   302	            currentRevision !== expectedRevision;
   303	
   304	          if (initialConflict || legacyReplacementConflict || casConflict) {
   305	            return [
   306	              new CodexOAuthProfileCommitConflict({
   307	                operation,
   308	                profileId: profile.subject.profileId,
   309	                subjectHash,
   310	                message:
   311	                  "The stored Codex OAuth profile no longer matches the fenced commit precondition.",
   312	              }),
   313	              profiles,
   314	            ] as const;
   315	          }
   316	
   317	          return [
   318	            undefined,
   319	            new Map([...profiles, [key, profile] as const]),
   320	          ] as const;
   321	        });
   322	
   323	        if (conflict !== undefined) {
   324	          return yield* conflict;
   325	        }
   326	
   327	        if (
   328	          operation === "markReauthenticationRequired" &&
   329	          profile.requiresReauthentication &&
   330	          Option.isSome(observer)
   331	        ) {
   332	          yield* observer.value.record({
   333	            type: "reauthenticationMarked",
   334	            operation,
   335	            profileKind: "subscription",
   336	            requiresReauthentication: true,
   337	          });
   338	        }
   339	
   340	        return profile;
   341	      });
   342	
   343	    return CodexOAuthProfileCommit.of({
   344	      initialWrite: Effect.fn("CodexOAuthProfileCommitMemory.initialWrite")(
   345	        (profile: CodexSubscriptionProfile) =>
   346	          writeProfile("initialWrite", profile)
   347	      ),
   348	      replace: Effect.fn("CodexOAuthProfileCommitMemory.replace")((input) =>
   349	        writeProfile("replace", input.profile, input.expectedRevision)
   350	      ),
   351	      replaceLegacy: Effect.fn("CodexOAuthProfileCommitMemory.replaceLegacy")(
   352	        (input) =>
   353	          writeProfile(
   354	            "replaceLegacy",
   355	            input.profile,
   356	            undefined,
   357	            input.expectedLegacyProfile
   358	          )
   359	      ),
   360	      refresh: Effect.fn("CodexOAuthProfileCommitMemory.refresh")((input) =>
   361	        writeProfile("refresh", input.profile, input.expectedRevision)
   362	      ),
   363	      markReauthenticationRequired: Effect.fn(
   364	        "CodexOAuthProfileCommitMemory.markReauthenticationRequired"
   365	      )((input) =>
   366	        writeProfile(
   367	          "markReauthenticationRequired",
   368	          input.profile,
   369	          input.expectedRevision
   370	        )
   371	      ),
   372	    });
   373	  }).pipe(Effect.withSpan("CodexOAuthProfileCommitMemory"))
   374	);
