   399	                (event.type === "refreshStarted" ? 1 : 0),
   400	              refreshSucceeded:
   401	                snapshot.counters.refreshSucceeded +
   402	                (event.type === "refreshSucceeded" ? 1 : 0),
   403	              refreshConflict:
   404	                snapshot.counters.refreshConflict +
   405	                (event.type === "refreshConflict" ? 1 : 0),
   406	              refreshWinnerUsed:
   407	                snapshot.counters.refreshWinnerUsed +
   408	                (event.type === "refreshWinnerUsed" ? 1 : 0),
   409	              reauthenticationMarked:
   410	                snapshot.counters.reauthenticationMarked +
   411	                (event.type === "reauthenticationMarked" ? 1 : 0),
   412	            },
   413	            events: [...snapshot.events, event],
   414	          }))
   415	      ),
   416	      snapshot: Ref.get(state),
   417	    });
   418	  }).pipe(Effect.withSpan("CodexOAuthObserverMemory"))
