   433	export const CodexOAuthRefreshLockMemory = Layer.effect(
   434	  CodexOAuthRefreshLock,
   435	  Effect.gen(function* makeCodexOAuthRefreshLockMemory() {
   436	    const leases = yield* Ref.make(
   437	      new Map<
   438	        string,
   439	        {
   440	          readonly owner: ReturnType<typeof Redacted.make<string>>;
   441	          readonly expiresAtEpochMillis: number;
   442	        }
   443	      >()
   444	    );
   445	
   446	    return yield* makeCodexOAuthRefreshLock({
   447	      acquire: (lease, nowEpochMillis) =>
   448	        Ref.modify(leases, (currentLeases) => {
   449	          const existingLease = currentLeases.get(lease.subjectHash);
   450	
   451	          if (
   452	            existingLease !== undefined &&
   453	            existingLease.expiresAtEpochMillis > nowEpochMillis
   454	          ) {
   455	            return [false, currentLeases] as const;
   456	          }
   457	
   458	          const nextLeases = new Map([
   459	            ...currentLeases,
   460	            [
   461	              lease.subjectHash,
   462	              {
   463	                owner: lease.owner,
   464	                expiresAtEpochMillis: lease.expiresAtEpochMillis,
   465	              },
   466	            ],
   467	          ]);
   468	
   469	          return [true, nextLeases] as const;
   470	        }),
   471	      release: (lease) =>
   472	        Ref.modify(leases, (currentLeases) => {
   473	          const existingLease = currentLeases.get(lease.subjectHash);
   474	
   475	          if (
   476	            existingLease === undefined ||
   477	            !Equal.equals(existingLease.owner, lease.owner)
   478	          ) {
   479	            return [false, currentLeases] as const;
   480	          }
   481	
   482	          const nextLeases = new Map(currentLeases);
   483	          nextLeases.delete(lease.subjectHash);
   484	
   485	          return [true, nextLeases] as const;
   486	        }),
   487	    });
   488	  }).pipe(Effect.withSpan("CodexOAuthRefreshLockMemory"))
   489	);
   490	
   491	export const CodexOAuthMemory = (
   492	  profiles: readonly CodexOAuthProfileType[] = [],
   493	  clientOptions: CodexOAuthClientMockOptions = {}
   494	) => {
   495	  const state = CodexOAuthMemoryProfilesLive(profiles);
   496	  const observer = CodexOAuthObserverMemory;
   497	  const client = CodexOAuthClientMock(clientOptions);
   498	  const refreshLock = CodexOAuthRefreshLockMemory;
   499	  const store = CodexProfileStoreMemoryLive.pipe(Layer.provide(state));
   500	  const commit = CodexOAuthProfileCommitMemory.pipe(
   501	    Layer.provideMerge(Layer.merge(state, observer))
   502	  );
   503	  const service = CodexOAuthServiceLive.pipe(
   504	    Layer.provideMerge(
   505	      Layer.mergeAll(store, commit, client, observer, refreshLock)
   506	    )
   507	  );
   508	
   509	  return Layer.mergeAll(store, commit, client, observer, refreshLock, service);
   510	};
"
}

