   133	          return yield* new CodexOAuthRefreshLockError({
   134	            operation: "release",
   135	            reason: "expired",
   136	            subjectHash: lease.subjectHash,
   137	            expiresAtEpochMillis: lease.expiresAtEpochMillis,
   138	            nowEpochMillis,
   139	            message: "Codex OAuth refresh-lock lease expired before release.",
   140	          });
   141	        }
   142	
   143	        const released = yield* provider.release(lease);
   144	
   145	        if (!released) {
   146	          return yield* new CodexOAuthRefreshLockError({
   147	            operation: "release",
   148	            reason: "release",
   149	            subjectHash: lease.subjectHash,
   150	            message:
   151	              "Codex OAuth refresh-lock lease is not owned by this invocation.",
   152	          });
   153	        }
