 52	export const makeCodexSubscriptionLogin = Effect.gen(
 53	  function* makeCodexSubscriptionLoginOperation() {
 54	    const browser = yield* CodexBrowserLauncher;
 55	    const callback = yield* CodexLoopbackCallback;
 56	    const commit = yield* CodexOAuthProfileCommit;
 57	    const http = yield* CodexOAuthHttpClient;
 58	    const protocol = yield* CodexSubscriptionAuthProtocolConfigService;
 59	    const store = yield* CodexProfileStore;
 60	
 61	    return CodexSubscriptionLogin.of({
 62	      run: Effect.fn("CodexSubscriptionLogin.run")((input) =>
 63	        Effect.gen(function* runCodexSubscriptionLogin() {
 64	          const existingProfile = yield* store.getProfile(input.subject).pipe(
 65	            Effect.map(Option.some),
 66	            Effect.catchTag("OAuthProfileNotFound", () =>
 67	              Effect.succeed(Option.none<CodexOAuthProfile>())
 68	            )
 69	          );
 70	          const material = yield* createCodexOAuthAuthorizationMaterial();
 71	          const callbackSession = yield* callback.open(material.state);
 72	          const authorizationSession =
 73	            yield* buildCodexOAuthAuthorizationSession(
 74	              material,
 75	              callbackSession.redirectUri
 76	            ).pipe(
 77	              Effect.provideService(
 78	                CodexSubscriptionAuthProtocolConfigService,
 79	                protocol
 80	              )
 81	            );
 82	
 83	          yield* browser.open(authorizationSession.authorizationUrl);
 84	
 85	          const authorizationCallback = yield* callbackSession.awaitCallback(
 86	            input.callbackTimeoutMillis
 87	          );
 88	          const tokens = yield* http.exchangeAuthorizationCode({
 89	            code: authorizationCallback.code,
 90	            codeVerifier: authorizationSession.codeVerifier,
 91	            redirectUri: authorizationCallback.redirectUri,
 92	          });
 93	          const expiry = yield* decodeCodexAccessTokenExpiry(
 94	            tokens.access_token
 95	          );
 96	          const now = yield* Clock.currentTimeMillis;
 97	
 98	          if (expiry.expiresAtEpochMillis <= now) {
 99	            return yield* new CodexSubscriptionAuthError({
100	              operation: "decodeTokenMetadata",
101	              reason: "tokenExpired",
102	              message: "The exchanged Codex OAuth access token is expired.",
103	            });
104	          }
105	
106	          const account = yield* decodeCodexAccountMetadata(tokens.id_token);
107	          const credentialRevision =
108	            yield* generateCodexOAuthCredentialRevision();
109	          const profile = yield* Schema.decodeUnknownEffect(
110	            CodexSubscriptionProfile
111	          )({
112	            profileVersion: 2,
113	            profileKind: "subscription",
114	            subject: input.subject,
115	            accessToken: Redacted.value(tokens.access_token),
116	            refreshToken: Redacted.value(tokens.refresh_token),
117	            expiresAtEpochMillis: expiry.expiresAtEpochMillis,
118	            accountId: Redacted.value(account.accountId),
119	            protocolScopeVersion: protocol.config.protocolScopeVersion,
120	            scopes: [...protocol.config.scopes],
121	            createdAtEpochMillis: Option.isSome(existingProfile)
122	              ? existingProfile.value.createdAtEpochMillis
123	              : now,
124	            updatedAtEpochMillis: now,
125	            lastRefreshedAtEpochMillis: now,
126	            credentialRevision,
127	            requiresReauthentication: false,
128	          }).pipe(
129	            Effect.mapError(
130	              () =>
131	                new CodexSubscriptionAuthError({
132	                  operation: "completeLogin",
133	                  reason: "tokenMetadataInvalid",
134	                  message:
135	                    "Unable to construct the subscription OAuth profile.",
136	                })
137	            )
138	          );
139	
140	          yield* Option.match(existingProfile, {
141	            onNone: () => commit.initialWrite(profile),
142	            onSome: (storedProfile) =>
143	              storedProfile.profileKind === "subscription"
144	                ? commit.replace({
145	                    profile,
146	                    expectedRevision: storedProfile.credentialRevision,
147	                  })
148	                : commit.replaceLegacy({
149	                    expectedLegacyProfile: storedProfile,
150	                    profile,
151	                  }),
152	          });
153	
154	          return yield* Schema.decodeUnknownEffect(
155	            CodexSubscriptionLoginResult
156	          )({
157	            profileId: input.subject.profileId,
158	            mode: "chatgpt",
159	            expiryCategory: "valid",
160	            refreshCapable: true,
161	            encryptedStore: "stored",
162	          }).pipe(
163	            Effect.mapError(
164	              () =>
165	                new CodexSubscriptionAuthError({
166	                  operation: "completeLogin",
167	                  reason: "tokenMetadataInvalid",
168	                  message: "Unable to encode the sanitized login result.",
169	                })
170	            )
171	          );
172	        }).pipe(Effect.scoped)
173	      ),
174	    });
175	  }
176	).pipe(Effect.withSpan("CodexSubscriptionLoginLive"));
