        })
      ).pipe(
        Effect.provideService(CodexOAuthRefreshLock, refreshLock),
        Effect.catchTag("CodexOAuthRefreshLockError", (error) =>
          error.reason === "contended"
            ? Effect.gen(function* readContendedWinner() {
