                const nowEpochMillis = yield* Clock.currentTimeMillis;

                if (
                  winner.expiresAtEpochMillis > nowEpochMillis &&
                  (observedCredentialRevision === undefined ||
                    winner.credentialRevision !== observedCredentialRevision)
